const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'Unknown workflow';
const ex = e.execution || {};
const err = ex.error || {};
const message = String(err.message || 'Unknown error').slice(0, 500);
const lastNode = ex.lastNodeExecuted || (err.node && err.node.name) || 'unknown node';
const subject = '[Support triage] Failure in ' + wf;
const text = ['A workflow failed.', '', 'Workflow: ' + wf, 'Node: ' + lastNode, 'Error: ' + message, 'Mode: ' + (ex.mode || ''), 'Execution: ' + (ex.url || ex.id || ''), '', 'No customer email was sent. Drafts are never sent automatically.'].join('\n');
return [{ json: { subject, text } }];
